AdcCommand& setParams(const ParamList& aParams) noexcept {
		parameters = aParams; 
		return *this; 
	}

AdcCommand& addParam(const string& name, const string& value) noexcept {
		parameters.push_back(name);
		parameters.back() += value;
		return *this;
	}

AdcCommand& addParam(const string& str) noexcept {
		parameters.push_back(str);
		return *this;
	}

inline void dispatch(const string& aLine, OnCommandParsedF&& aOnCommandParsedF) noexcept {
		dispatch(aLine, false, std::move(aOnCommandParsedF));
	}

template<typename... ArgT>
	void dispatch(const string& aLine, bool aNmdc, const OnCommandParsedF& aOnCommandParsedF, ArgT&&... args) noexcept {
		try {
			AdcCommand c(aLine, aNmdc);
			if (!aNmdc && aOnCommandParsedF) {
				aOnCommandParsedF(c);
			}

			dispatch(c, std::forward<ArgT>(args)...);
		} catch (const ParseException&) {
			dcdebug("Invalid ADC command: %.50s\n", aLine.c_str());
			return;
		}
	}

template<typename... ArgT>
	void dispatch(AdcCommand& aCmd, ArgT&&... args) noexcept {
#define C(n) case AdcCommand::CMD_##n: ((T*)this)->handle(AdcCommand::n(), aCmd, std::forward<ArgT>(args)...); break
		switch(aCmd.getCommand()) {
			C(SUP);
			C(STA);
			C(INF);
			C(MSG);
			C(SCH);
			C(RES);
			C(CTM);
			C(RCM);
			C(GPA);
			C(PAS);
			C(QUI);
			C(GET);
			C(GFI);
			C(SND);
			C(SID);
			C(CMD);
			C(NAT);
			C(RNT);
			C(ZON);
			C(ZOF);
			C(TCP);
			C(PMI);
		default: 
			// dcdebug("Unknown ADC command: %.50s\n", aCmd.toString().c_str());
			break;
#undef C
		}
	}

bool add(const string& aSupport) noexcept {
		dcassert(aSupport.length() == 4);

		WLock l(cs);
		if (ranges::find(supports, aSupport) != supports.end()) {
			return false;
		}

		supports.push_back(aSupport);
		return true;
	}

bool remove(const string& aSupport) noexcept {
		dcassert(aSupport.length() == 4);

		WLock l(cs);
		auto i = ranges::find(supports, aSupport);
		if (i != supports.end()) {
			supports.erase(i);
			return true;
		}

		return false;
	}

bool includes(const string& aSupport) const noexcept {
		dcassert(aSupport.length() == 4);

		RLock l(cs);
		return ranges::find(supports, aSupport) != supports.end();
	}

StringList getAll() const noexcept {
		RLock l(cs);
		return supports;
	}

void clear() noexcept {
		WLock l(cs);
		supports.clear();
	}

void replace(const StringList& aSupports) noexcept {
		dcassert(ranges::all_of(aSupports, [](const string& aSupport) { return aSupport.length() == 4; }));
		WLock l(cs);
		supports = aSupports;
	}

void SendCommandMessage(const string& aMess, uint8_t aType, uint8_t aDirection, const string& aIP) {
		fire(ProtocolCommandManagerListener::DebugCommand(), aMess, aType, aDirection, aIP);
	}
